import { Router } from "express";
import { deleteAll, getDownloadAllFiles, getDownloadFileById, postCollageMaker, postCompressImage, postConvertImage, postCropFace, postCropImage, postResizeImage, postWatermarkingImage, } from "../controllers/index.js";
import { uploadsMiddleware } from "../middlewares/uploads.js";
import { uploadsWmMiddleware } from "../middlewares/watermarkUploads.js";
import { changePassword, changeUsername, disableTwoFactor, forgotPassword, getCsrfToken, getGeo, getUser, getUsers, loginUser, logoutUser, removeProfileImg, resetPassword, setupTwoFactor, signupUser, uploadProfileImg, verifyEnableTwoFactor, verifyLoginTwoFactor, } from "../controllers/userController.js";
import { verifyToken } from "../middlewares/verifyToken.js";
import { csrfProtection } from "../middlewares/csrfProtection.js";
import { profileImageUpload } from "../middlewares/profileImageUpload.js";
import { uploadLimiter } from "../middlewares/uploadLimiter.js";
const router = Router();
// router.get("/", getHomePage);
// premium
router.post("/crop-face", uploadsMiddleware, postCropFace);
router.post("/collage", uploadsMiddleware, postCollageMaker);
router.get("/download/:fileId", getDownloadFileById);
router.get("/download-all", getDownloadAllFiles);
router.get("/convert-image/delete-all", deleteAll);
// users
router.get("/users", getUsers);
router.get("/user", verifyToken, getUser);
router.get("/csrf-token", csrfProtection, getCsrfToken);
router.post("/signup", signupUser);
router.post("/login", loginUser);
router.post("/logout", csrfProtection, verifyToken, logoutUser);
router.post("/upload-profile-image", profileImageUpload, verifyToken, uploadProfileImg);
router.post("/remove-profile-image", verifyToken, removeProfileImg);
// router.post("/remove-tokens", removeTokens);
router.get("/geo", getGeo);
router.post("/forgot-password", forgotPassword);
router.post("/reset-password/:resetToken", resetPassword);
router.post("/change-password", verifyToken, csrfProtection, changePassword);
router.post("/change-username", verifyToken, csrfProtection, changeUsername);
router.post("/2fa/setup", verifyToken, csrfProtection, setupTwoFactor);
router.post("/2fa/verify-enable", verifyToken, csrfProtection, verifyEnableTwoFactor);
router.post("/2fa/verify-login", verifyLoginTwoFactor);
router.post("/2fa/disable", verifyToken, csrfProtection, disableTwoFactor);
router.post("/convert", uploadsMiddleware, postConvertImage);
router.post("/resize", uploadsMiddleware, postResizeImage);
router.post("/crop", uploadsMiddleware, postCropImage);
router.post("/compress", uploadsMiddleware, uploadLimiter, postCompressImage);
router.post("/watermark", uploadsWmMiddleware, postWatermarkingImage);
export default router;
